// Facts summarize linked sources. Every persona, scene, choice and consequence is fictional teaching material.
const option=(text,result)=>({text,result});
const scene=(time,title,story,barrier,options)=>({time,title,story,barrier,options});
const source=(title,date,url)=>({title,date,url});
window.SCENARIOS=[
{id:'tuvalu',country:'투발루',region:'바이투푸섬',theme:'환경',title:'바다가 가까워진 우리 집',role:'해안 가까이 사는 학생',wish:'가족과 이웃이 있는 이 섬에서 계속 배우고 살아가고 싶다.',summary:'해안 침식과 침수 속에서 집, 학교, 고향의 의미를 생각합니다.',facts:['바이투푸섬은 해수면 상승, 파도에 의한 침수, 폭풍해일, 해안 침식과 염수 유입 위험을 겪는다.','낮고 좁은 땅에 생활 시설이 집중되어 있어 해안 위험이 이동 경로와 기반시설에도 영향을 준다.','UNDP 사업은 지역의 해안 적응 역량을 높이는 대응을 추진한다.'],sources:[source('UNDP · 바이투푸 해안 적응 사업','게시일 미표기 · 2025년 국가계획 연계','https://www.adaptation-undp.org/projects/vaitupu-coastal-adaptation-project-vcap')],question:'주민이 고향에 머물 권리와 안전을 함께 지키려면 어떤 선택지가 필요할까?',actors:'주민·투발루 정부·기후재정 지원국·국제기구',scenes:[
scene('아침','돌아가는 등굣길','어제 물이 들어온 길을 가족이 함께 살펴본다. 평소 길을 피하면 학교까지 돌아가야 한다. 이웃은 집 주변을 정리하는 데 도움이 필요하다고 말한다.','안전한 길과 해안 보호 시설은 학생의 노력만으로 만들 수 없다.',[option('가족과 확인한 우회로로 등교한다','수업에 참여할 수 있지만 이동에 더 많은 시간이 든다. 집 정리는 다른 가족에게 남는다.'),option('가족과 집 주변을 정리하고 학교에 상황을 알린다','집안의 일을 나누지만 수업을 놓친다. 재난 때 학습을 이어갈 지원이 필요해진다.')]),
scene('낮','우리 집의 다음 계절','가족이 거처를 어떻게 지킬지 의논한다. 집을 보강하는 데도, 다른 곳으로 옮기는 데도 비용이 든다. 친척과 이웃은 가까이에 있다.','거주지를 결정할 권리와 적응 비용을 함께 고려해야 한다.',[option('고향에 머무르며 집 보강을 우선 논의한다','관계를 지킬 수 있지만 우리 집만 보강해도 길과 공동시설의 문제는 남는다.'),option('더 안전한 거처로 옮길 가능성을 알아본다','위험을 줄일 가능성이 생기지만 비용과 학교, 공동체 관계를 함께 검토해야 한다.')]),
scene('저녁','해안 계획에 우리의 목소리를','주민 모임에서 해안 보호와 생활 기반시설 중 무엇을 먼저 요청할지 의견을 모은다. 모든 요청을 한 번에 실행할 수는 없다.','장기적 해수면 변화와 주민 의사를 함께 반영하는 공적 계획이 필요하다.',[option('집 주변 해안 보호를 우선 요청한다','주거의 긴급함을 전달한다. 다른 구역과 공공시설에 미치는 영향도 확인해야 한다.'),option('학교와 이동로의 안전을 우선 요청한다','여러 사람이 쓰는 시설을 강조한다. 위험에 놓인 개별 가구를 위한 지원도 남겨 두어야 한다.')])]},
{id:'pakistan',country:'파키스탄',region:'자코바바드',theme:'환경',title:'쉴 수 없는 더운 하루',role:'하루 일거리로 생계를 잇는 성인 노동자',wish:'건강을 지키면서 가족의 생활비도 마련하고 싶다.',summary:'폭염에 대한 같은 조언이 모두에게 가능한지 살펴봅니다.',facts:['앰네스티는 2023년 자코바바드와 라호르의 소외계층 인터뷰를 바탕으로 폭염과 건강권을 조사했다.','폭염의 영향은 소득과 생활·노동 조건에 따라 다르게 나타난다.'],sources:[source('국제앰네스티 · A Burning Emergency','2023.6.4. · 당시 조사 사례','https://www.amnesty.org/en/documents/asa33/6823/2023/en/')],question:'폭염에 일을 쉬기 어려운 사람의 건강과 소득을 함께 보장하려면?',actors:'노동자·고용주·지방정부·국제 기후재정 주체',scenes:[
scene('아침','오늘 일할 수 있나요?','더운 날이다. 일터에서는 오늘 나올 수 있는지 묻는다. 일을 쉬면 가족의 생활비가 줄 수 있다.','휴식의 권리를 실현하려면 소득 보장과 노동환경 개선이 함께 필요하다.',[option('오늘은 일을 쉬고 가족과 지출을 조정한다','더위에 노출되는 시간은 줄지만 생활비를 줄일 방법을 찾아야 한다.'),option('작업 시간 조정과 휴게공간을 먼저 요청한다','소득과 안전을 함께 요구한다. 실제 조정 여부는 고용주와 제도에 달려 있어 답을 기다려야 한다.')]),
scene('낮','시원한 공간까지의 거리','동네에서 더위를 피할 공간을 찾는다. 집에서 쉴 수도 있지만 냉방 여건이 충분하지 않다는 설정이다.','냉방과 공공 쉼터에 접근할 수 있는 조건은 가구마다 다르다.',[option('이웃과 함께 이용할 수 있는 공공 공간을 알아본다','함께 정보를 찾을 수 있다. 거리와 운영시간이 맞는지 확인해야 한다.'),option('집에서 쉬며 냉방 비용을 가족과 의논한다','익숙한 곳에 머무르지만 추가 비용이 생활비를 압박한다.')]),
scene('저녁','개인의 주의만으로 충분할까','동료들과 필요한 지원을 정리한다. 쉬라는 안내는 들었지만 쉴 수 있게 하는 조건은 아직 부족하다.','기후위기에 대응할 책임을 저소득 노동자 개인에게만 맡길 수 없다.',[option('폭염 시 유급휴식과 작업시간 조정을 제안한다','일하는 동안의 조건을 바꾸는 제안이다. 적용 범위와 현장 점검이 필요하다.'),option('가까운 공공 쉼터와 냉방비 지원을 제안한다','생활공간의 보호를 넓힌다. 비공식 노동자의 소득 문제도 함께 다뤄야 한다.')])]},
{id:'bangladesh',country:'방글라데시',region:'해안의 염수 유입 지역',theme:'물',title:'물은 있지만 마실 수 없다',role:'가족과 식수를 마련하는 학생',wish:'물을 걱정하지 않고 학교에 가고 싶다.',summary:'염분이 높아진 물, 식수 비용과 시간 사이에서 선택합니다.',facts:['해안 지역에서는 지표수와 지하수에 바닷물이 유입되어 안전한 식수 접근을 제한한다.','유니세프와 협력 기관은 빗물·연못물을 처리해 지하에 저장하는 관리형 지하수 함양 방식을 도입했다.'],sources:[source('UNICEF · 해안 지역의 염수 유입과 지하수 함양','본문 발행일 미표기','https://www.unicef.org/documents/managed-aquifer-recharge-mar-protecting-communities-saline-intrusion-groundwater-costal')],question:'염분 유입 지역에서 비용과 유지관리까지 고려한 식수 공급은 어떻게 가능할까?',actors:'주민·수도 담당 기관·지방정부·기술 지원 기관',scenes:[
scene('아침','등교 전에 해야 할 일','가족이 사용할 식수를 마련해야 한다. 가까운 물은 식수로 적합한지 확인되지 않았다. 검증된 공급처에 다녀오려면 시간이 든다.','물의 양이 많아도 안전한 식수에 접근할 수 있다는 뜻은 아니다.',[option('가족과 검증된 공급처에 다녀온다','안전성이 확인된 물을 구하지만 아침 학습 시간이 줄어든다.'),option('오늘은 구매 가능한 식수를 알아본다','시간을 아낄 수 있지만 가족 지출이 늘어난다. 가격과 안전성 확인도 필요하다.')]),
scene('낮','장비 하나면 해결될까','학교에서 물 문제 해결 아이디어를 모은다. 친구가 아무 정수기나 설치하면 되는지 묻는다.','염분 제거 성능과 수질 확인 없이 장비만 보급하면 적합한 해결책이 아닐 수 있다.',[option('빗물 저장과 처리 방식을 조사한다','이용 가능한 강우와 저장 공간을 확인해야 한다. 건기에도 충분할지 질문이 생긴다.'),option('염분을 처리할 수 있는 설비를 조사한다','수질에 맞는 기술을 찾는다. 전력, 비용, 부품과 관리 인력을 함께 따져야 한다.')]),
scene('저녁','설비를 누가 관리할까','주민 회의에서 공동 식수시설을 논의한다. 설치 후에도 수질 검사와 수리가 계속 필요하다.','설치비뿐 아니라 지속적인 관리와 공정한 접근이 핵심이다.',[option('주민 관리팀과 공적 유지관리 지원을 제안한다','현지 참여를 살린다. 무급 노동 부담이 특정 주민에게 몰리지 않도록 해야 한다.'),option('공공기관이 운영하고 주민이 점검에 참여하도록 제안한다','공적 책임을 명확히 한다. 문제 발생 때 신속히 대응할 창구가 필요하다.')])]},
{id:'somalia',country:'소말리아',region:'가뭄 피해 농목축 지역',theme:'물',title:'비를 기다리는 가족',role:'농목축 가구의 성인 구성원',wish:'가족이 먹고 마실 물과 생계를 함께 지키고 싶다.',summary:'물 부족이 식량과 생계로 이어지는 과정을 살펴봅니다.',facts:['2025년 말 가뭄과 강우 부족이 물 부족, 목초지 손실과 물·식량 가격 상승을 심화했다.','지역별 강우와 피해는 달랐으며 분쟁과 지원 재원 부족도 대응을 어렵게 했다.'],sources:[source('UNICEF · 소말리아 연말 상황보고서','2025년 상황 · 2026년 발행','https://www.unicef.org/media/179031/file/Somalia-Humanitarian-Situation-Report-No.8-%28End-of-Year%29-31-December-2025.pdf')],question:'긴급 식수 지원을 장기적인 생계 회복과 어떻게 연결할까?',actors:'농목축 주민·정부·급수 및 식량 지원 기관·공여국',scenes:[
scene('아침','오른 물값','오늘 살 물의 가격이 가족 예산에 부담이 된다. 물을 사고 나면 다른 필수품을 살 돈이 줄어든다.','가뭄은 물의 공급과 가격을 바꾸고 가계 전체에 영향을 준다.',[option('물을 구매하고 다른 지출을 줄인다','오늘 필요한 물을 마련하지만 식료품 등 다른 필요가 남는다.'),option('공동 급수 지원 가능 여부를 먼저 확인한다','지출을 줄일 가능성이 있지만 실제 이용 가능성과 대기시간을 확인해야 한다.')]),
scene('낮','가족의 생계 자산','가축을 유지하려면 물과 먹이가 필요하다. 가족은 생계 자산 일부를 팔아 당장의 비용을 마련할지 의논한다.','생계 자산을 잃으면 비가 온 뒤에도 회복이 어려워질 수 있다.',[option('일부 자산을 처분하는 방안을 검토한다','당장 현금을 마련할 수 있지만 이후 생계를 회복할 기반이 줄어든다.'),option('지원 정보를 찾으며 생계 자산을 지키려 한다','장기 회복의 기반을 남기려 한다. 당장 필요한 비용을 마련할 대안이 필요하다.')]),
scene('저녁','지원 요청을 적다','공동체에서 긴급한 필요와 다음 계절의 필요를 구분해 적는다. 물을 받은 뒤에도 생활이 안정되는 것은 아니다.','식수·영양·생계·안전은 서로 연결되어 있다.',[option('급수와 영양 지원을 우선 요청한다','지금의 필요를 중심에 둔다. 이후 소득과 생산 회복 계획을 이어 붙여야 한다.'),option('급수와 함께 생계 회복 지원을 요청한다','현재와 이후를 연결한다. 긴급 지원이 장기 사업을 기다리느라 늦어지지 않아야 한다.')])]},
{id:'gaza',country:'팔레스타인',region:'가자지구',theme:'물',title:'급수 소식을 기다리는 하루',role:'피란 생활 중인 성인 보호자',wish:'가족이 안전하게 물을 구하고 일상을 되찾기를 바란다.',summary:'시설뿐 아니라 물을 공급하는 길과 자원의 중요성을 살펴봅니다.',facts:['2026년 5월 유니세프는 식수 접근의 불안정과 급수차 의존을 보고했다.','급수 경로의 안전 문제와 에너지·정수 약품·부품 부족이 물 공급을 제약했다.'],sources:[source('UNICEF · 가자지구 물·위생 상황보고','2026.5.29.','https://www.unicef.org/sop/reports/unicef-state-palestine-humanitarian-situation-update-wash-gaza-strip')],question:'급수시설의 운영과 물을 구하러 가는 사람의 안전을 함께 보장하려면?',actors:'주민·분쟁 당사자·인도지원 기관·국제사회',scenes:[
scene('아침','정해지지 않은 급수 시간','가족이 급수 소식을 확인한다. 공급 일정이 확실하지 않아 다른 일을 계획하기 어렵다.','불확실한 공급은 물을 기다리는 시간까지 사람들의 삶을 제약한다.',[option('확인된 급수 안내를 기다리며 오늘 일정을 미룬다','헛걸음을 피하려 하지만 돌봄과 다른 일의 시간이 계속 바뀐다.'),option('이웃과 공식 안내를 나누고 역할을 분담한다','정보 확인 부담을 나눈다. 정보 공유만으로 물 공급 자체를 늘릴 수는 없다.')]),
scene('낮','부족한 것은 물만이 아니다','지원기관의 설명을 통해 설비 운영에 부품과 정수 약품이 필요하다는 것을 알게 된다.','시설이 존재해도 안전한 접근, 에너지와 부품 없이는 작동하기 어렵다.',[option('당장의 급수차 지원 필요를 전달한다','긴급한 물 공급을 요청한다. 지속적인 운송과 경로 안전이 확보되어야 한다.'),option('시설 복구와 운영 물자 지원 필요를 전달한다','장기적인 공급을 요청한다. 복구 전까지 긴급 급수도 함께 필요하다.')]),
scene('저녁','우리의 필요를 설명하다','가족과 이웃의 물 사용 어려움을 정리한다. 개인정보와 위치를 자세히 공개하지 않고도 필요를 전달할 수 있다.','지원 계획에는 양뿐 아니라 안전, 접근성과 돌봄 부담이 포함되어야 한다.',[option('급수 일정과 가까운 공급 지점 개선을 요청한다','접근의 문제를 드러낸다. 현장의 안전성과 공급 여건을 담당 기관과 확인해야 한다.'),option('시설 운영 자원의 안정적 공급을 요청한다','물 공급의 구조적 제약을 짚는다. 주민의 당장 필요한 물도 동시에 보장해야 한다.')])]},
{id:'haiti',country:'아이티',region:'포르토프랭스의 임시 거처',theme:'빈곤',title:'집을 떠난 뒤의 식탁',role:'집을 떠나 임시 거처에서 지내는 성인',wish:'가족의 식사를 마련하고 다시 안정적으로 일하고 싶다.',summary:'폭력과 강제이주가 식량 접근을 막는 과정을 살펴봅니다.',facts:['WFP는 2025년 무장 폭력, 강제이주, 경제 혼란과 식량 생산 차질이 기아를 심화한다고 보고했다.','포르토프랭스에서 학교·공공건물 등에 머무는 국내실향민이 식수·식량·의료 접근에 어려움을 겪었다.'],sources:[source('WFP · 폭력·강제이주와 아이티의 기아','2025년 자료','https://www.wfp.org/news/persistent-violence-and-displacement-lead-record-hunger-haiti-needs-skyrocket')],question:'식량을 보내는 일과 안전한 생활·소득 회복을 어떻게 함께 추진할까?',actors:'국내실향민·정부·지역 생산자·인도지원 기관',scenes:[
scene('아침','낯선 곳에서 아침을','익숙한 시장과 일터에서 떨어진 임시 거처다. 가족은 오늘 이용할 수 있는 식량 지원과 구매 방법을 알아본다.','먹을 것을 구하는 능력은 소득뿐 아니라 안전과 이동 조건에 달려 있다.',[option('확인된 식량 지원 일정을 알아본다','당장의 식사에 도움이 될 수 있지만 지원 여부와 시간에 일상을 맞춰야 한다.'),option('안전하게 이용 가능한 판매처와 가격을 확인한다','선택 가능한 먹거리를 찾는다. 제한된 생활비가 부담으로 남는다.')]),
scene('낮','일을 찾는 시간과 돌봄','수입을 되찾고 싶지만 임시 거처에서 가족을 돌보는 일도 필요하다.','강제이주는 일자리와 돌봄의 연결망을 함께 흔든다.',[option('가족과 돌봄을 나누고 안전한 일자리 정보를 찾는다','생계 회복을 준비한다. 이동과 실제 채용 가능성은 아직 불확실하다.'),option('오늘은 돌봄에 집중하며 생활 지원을 알아본다','가족의 필요를 살핀다. 소득이 생기기 전까지 버틸 지원이 필요하다.')]),
scene('저녁','식량이 도착한 다음은?','지원의 우선순위에 대한 의견을 모은다. 오늘의 식사와 다음 달의 생활을 함께 생각한다.','인도적 접근과 지역 생산·소득 회복이 함께 필요하다.',[option('안전한 식량 배분과 식수 공급을 먼저 요청한다','긴급한 필요를 명확히 한다. 오래 머물게 될 경우의 생계 대책도 필요하다.'),option('긴급 지원에 현금·생계 회복 지원을 연결해 요청한다','다음 생활을 준비한다. 시장이 안전하게 작동하는지 함께 확인해야 한다.')])]},
{id:'ghana',country:'가나',region:'서부북부 지역 카카오 공동체',theme:'빈곤',title:'카카오 밭과 교실 사이',role:'카카오 재배 가구의 학생',wish:'가족이 안정적으로 생활하고 나도 꾸준히 학교에 다니고 싶다.',summary:'가계 소득과 아동의 교육·안전이 연결된 상황을 살펴봅니다.',facts:['ILO는 카카오 재배 공동체의 위험한 아동 노동이 교육과 안전을 위협한다고 설명한다.','불규칙한 강우와 기온 상승 등에 따른 수확 감소는 가계 빈곤과 아동 노동 위험을 악화시킨다.','2025~2026년 사업은 생계 대안과 기후 대응, 아동 보호를 함께 추진한다.'],sources:[source('ILO · 카카오 생산 지역 아동 노동 근절과 기후 대응','2025~2026년 사업','https://www.ilo.org/projects-and-partnerships/projects/strengthening-resilience-climate-change-elimination-child-labour-cocoa')],question:'아동의 교육과 안전을 지키면서 농가의 소득도 안정시키려면?',actors:'학생·농가·학교·정부·카카오 구매 기업',scenes:[
scene('아침','가족의 걱정이 들린다','수입이 줄어든 가족이 일손과 생활비를 걱정한다. 나도 걱정되지만 오늘 학교에 가고 싶다.','학생에게 가족 생계를 해결할 책임을 넘기지 않는 지원이 필요하다.',[option('학교에 가서 신뢰하는 교사에게 어려움을 알린다','수업과 상담의 기회를 얻는다. 가족에게 실제 도움이 될 지원을 함께 찾아야 한다.'),option('보호자와 등교를 지킬 수 있는 지원 방법을 의논한다','내 바람을 전한다. 대화만으로 소득 부족이 해결되지는 않는다.')]),
scene('낮','지원은 어디에 닿아야 할까','학교에서 필요한 지원에 대한 학생 의견을 묻는다. 학습비 부담과 가족 소득 문제가 모두 떠오른다.','교육 지원과 가계의 생계 지원은 함께 설계할 수 있다.',[option('학습비·급식 등 학교생활 지원을 말한다','계속 배우기 위한 비용을 줄일 수 있다. 가계의 생산과 수입 문제는 남는다.'),option('보호자의 안정적인 수입을 위한 지원도 말한다','아동 노동의 배경을 짚는다. 소득 지원이 실제 교육권 개선으로 이어지는지 살펴야 한다.')]),
scene('저녁','초콜릿을 만드는 연결','우리 마을의 카카오가 먼 곳의 제품이 된다는 이야기를 듣는다. 구매 기업에 묻고 싶은 내용을 정한다.','공급망의 책임을 학생이나 농가 한쪽에만 맡길 수 없다.',[option('위험한 아동 노동을 확인하고 개선하는 절차를 묻는다','기업의 점검 책임을 묻는다. 거래 중단만으로 가계가 더 어려워지지 않도록 개선 지원이 필요하다.'),option('농가 소득과 기후 대응을 어떻게 지원하는지 묻는다','생활 기반을 묻는다. 아동 보호와 학교 접근을 확인하는 장치도 함께 필요하다.')])]},
{id:'sudan',country:'수단 → 차드',region:'차드 동부의 난민 수용 지역',theme:'난민',title:'국경을 넘은 뒤에도',role:'수단에서 차드로 피란한 학생',wish:'안전하게 지내고 다시 공부하며 친구를 만나고 싶다.',summary:'난민과 기존 주민이 함께 필요한 생활 기반을 찾아봅니다.',facts:['수단 전쟁을 피해 차드로 이동한 사람들에게 거처·식량·식수·위생 지원이 필요하다.','NRC는 차드 동부에서 난민과 수용 지역 주민을 위한 학교시설과 교사 부족을 보고했다.'],sources:[source('NRC · 수단에서 차드로의 강제이주','2025.1.','https://www.nrc.no/news/2025/january/war-in-sudan-nearly-one-million-people-forcibly-displaced-to-chad'),source('UNHCR · 차드 현황','갱신형 페이지 · 수치는 별도 사용하지 않음','https://www.unhcr.org/chad')],question:'난민과 수용 지역 주민의 권리를 함께 보장하는 지원은 어떤 모습일까?',actors:'난민·차드 지역 주민·정부·UNHCR·교육 지원 기관',scenes:[
scene('아침','다시 공부할 수 있을까','새로운 곳에서 학교에 갈 방법을 알아본다. 가족은 생활 지원 안내도 확인해야 한다.','피란 이후에도 학습을 이어 갈 시설과 인력이 필요하다.',[option('보호자와 학교·학습 공간 정보를 먼저 찾는다','배움을 이어 갈 가능성을 찾는다. 등록과 실제 자리가 있는지 확인해야 한다.'),option('보호자와 생활 지원 안내를 먼저 확인한다','가족의 당장 필요한 정보를 얻는다. 학습 계획을 다시 잡을 시간이 필요하다.')]),
scene('낮','함께 쓰는 교실','수용 지역의 학생들도 교실과 교사가 부족하다는 이야기를 듣는다.','난민과 기존 주민 모두의 교육권을 보장할 기반시설 투자가 필요하다.',[option('함께 이용할 교실과 교사 확충을 제안한다','공통의 필요를 드러낸다. 교육 언어와 학습 공백에 맞춘 지원도 필요하다.'),option('학습 공백을 메우는 별도 보충수업을 제안한다','피란으로 놓친 배움을 돕는다. 일시적 수업 이후 정규교육과 연결해야 한다.')]),
scene('저녁','이웃과 미래를 이야기하다','주민과 난민의 의견을 함께 듣는 자리를 가정한다. 내가 가장 말하고 싶은 필요는 무엇일까?','지원받는 사람의 의견과 지역의 수용 역량을 함께 반영해야 한다.',[option('공동 식수시설과 학교 확충을 말한다','함께 쓰는 기반을 강조한다. 가장 취약한 가구의 접근도 따로 확인해야 한다.'),option('안전한 생활과 학습 상담 창구를 말한다','어려움을 전달할 통로를 강조한다. 제기된 문제를 실제로 해결할 자원이 필요하다.')])]},
{id:'rohingya',country:'미얀마 → 방글라데시',region:'콕스바자르 난민캠프',theme:'난민',title:'학교의 문이 닫힌 아침',role:'로힝야 난민 학생',wish:'배움을 멈추지 않고 내가 공부한 것을 인정받고 싶다.',summary:'학습 공간, 비용, 학력 인정의 차이를 살펴봅니다.',facts:['HRW는 2025년 원조 삭감으로 난민캠프 학습센터가 문을 닫았다고 보고했다.','로힝야 공동체가 운영하는 학교는 공식 인정·재정 지원 부족과 학비 문제를 겪었다.','이 보고서는 난민 교사와 공동체의 교육 활동 참여를 강조한다.'],sources:[source('Human Rights Watch · 원조 삭감과 로힝야 교육','2025.6.25. · 당시 상황','https://www.hrw.org/news/2025/06/25/bangladesh-foreign-aid-cuts-affect-rohingya-childrens-education')],question:'난민 공동체의 교육 노력을 지원하면서 학력 인정까지 보장하려면?',actors:'난민 학생·로힝야 교사·방글라데시 정부·공여기관',scenes:[
scene('아침','오늘은 어디에서 배울까','다니던 학습센터의 운영이 멈춘 상황을 가정한다. 가족과 다른 배움의 길을 찾는다.','교육 재원 삭감은 학생이 스스로 바꿀 수 없는 조건이다.',[option('공동체 학교의 등록과 학비를 알아본다','수업을 이어 갈 길을 찾는다. 가족이 비용을 감당할 수 있는지 확인해야 한다.'),option('교사와 친구들에게 함께 공부할 방법을 묻는다','연결을 유지할 수 있다. 정규 수업과 교재를 대신하기에는 한계가 있다.')]),
scene('낮','배웠다는 것을 증명하려면','열심히 공부해도 공식 학력으로 인정받기 어렵다는 이야기를 듣는다.','학습 기회와 학력 인정은 관련되지만 서로 다른 문제다.',[option('학습 기록을 모으고 인정 절차를 문의한다','나의 배움을 남길 수 있다. 기록 자체가 공식 인증을 보장하지는 않는다.'),option('교사들과 함께 학교 인정의 필요를 전달한다','공동의 요구를 만든다. 정부와 지원기관의 결정이 필요하다.')]),
scene('저녁','우리에게 묻는 학교 지원','지원 계획에서 어떤 내용을 먼저 강조할지 의견을 낸다.','지원은 난민을 수동적인 수혜자로만 보는 대신 공동체의 역량을 반영해야 한다.',[option('공동체 교사 지원과 학비 부담 완화를 말한다','이미 이어지는 교육을 뒷받침한다. 학력 인증과 교육의 질도 함께 다뤄야 한다.'),option('학교의 공식 인정과 안정적인 재정을 말한다','지속성을 강조한다. 제도가 바뀌기 전의 학습 공백도 줄여야 한다.')])]},
{id:'afghanistan',country:'아프가니스탄',region:'중등교육 접근이 제한된 지역',theme:'인권',title:'배우고 싶은 다음 학년',role:'초등교육 이후 진학이 막힌 여학생',wish:'다음 학년에서 배우고 내 미래를 스스로 선택하고 싶다.',summary:'교육의 도구와 교육받을 권리가 어떻게 다른지 생각합니다.',facts:['UNESCO의 2025년 자료는 탈레반의 정책으로 여학생과 여성의 중등·고등교육 접근이 차단되었다고 설명한다.','학교 부족과 별개로 제도적으로 교육권을 제한하는 문제다.'],sources:[source('UNESCO · 아프가니스탄 교육권 검토','2025년 자료','https://www.unesco.org/en/articles/banned-education-review-right-education-afghanistan?hub=412'),source('국제앰네스티 · 교육권을 말하는 당사자','2025.1.24.','https://www.amnesty.org/en/latest/campaigns/2025/01/ignorance-is-no-match-for-the-power-of-knowledge-and-education/')],question:'대체 학습 지원과 여학생의 정규교육권 회복을 어떻게 함께 추진할까?',actors:'여학생·가족·현지 교육자·교육권 제한 당국·국제사회',scenes:[
scene('아침','시간표가 사라진 하루','새로운 학년의 수업을 듣고 싶지만 진학이 제한된 상황이다. 오늘 배움을 이어갈 방법을 가족과 의논한다.','개인의 의욕이 부족해서가 아니라 교육 접근을 막는 제도가 문제다.',[option('구할 수 있는 교재로 학습 계획을 세운다','배움을 이어가려 한다. 교사의 지도와 정규 진학을 대신할 수는 없다.'),option('안전하게 이용 가능한 원격 학습 자원을 확인한다','다른 학습 경로를 찾는다. 기기·통신·비용의 제약이 있고 정규교육권 회복과는 다르다.')]),
scene('낮','혼자 공부하며 생기는 질문','배운 내용이 궁금해도 바로 질문할 교사가 없다. 미래의 학업을 생각하면 답답하다.','학습 자료뿐 아니라 지도, 친구와의 교류, 공인된 진학 경로가 필요하다.',[option('질문을 적어 신뢰하는 보호자와 도움받을 방법을 찾는다','학습의 필요를 구체화한다. 도움을 받을 수 있는 범위는 제한적이다.'),option('지금 필요한 교육 지원을 목록으로 적는다','막연한 어려움을 구체적으로 표현한다. 목록만으로 제도적 제한이 바뀌지는 않는다.')]),
scene('저녁','내가 바라는 교육','개인 신원과 위치를 공개하지 않는 교실 활동으로, 필요한 변화에 대한 글을 작성한다.','대체 학습 지원이 차별적 교육 제한을 정당화해서는 안 된다.',[option('교사·교재·통신 등 당장의 학습 지원을 강조한다','현재 배움의 공백을 줄일 필요를 말한다. 학교로 돌아갈 권리도 함께 요구해야 한다.'),option('여학생의 정규교육 접근 회복을 강조한다','핵심적인 권리 문제를 밝힌다. 변화 전까지의 학습·정서적 지원도 필요하다.')])]},
{id:'congo',country:'콩고민주공화국',region:'루알라바주 콜웨지 주변',theme:'인권',title:'배터리 뒤에 있는 우리 집',role:'광산 확장 지역에 사는 성인 주민',wish:'집과 생계, 이웃과의 관계를 지키고 결정에 참여하고 싶다.',summary:'친환경 전환 과정의 주거권과 기업 책임을 살펴봅니다.',facts:['앰네스티와 IBGDH는 구리·코발트 산업 광산 확장 과정의 강제퇴거와 부적절한 이주·보상 사례를 조사했다.','2023년 보고서는 주로 2022년 콜웨지 주변 현장 조사를 바탕으로 한다.','보고서는 에너지 전환의 필요성과 주민의 권리를 함께 다룬다.'],sources:[source('국제앰네스티·IBGDH · 광산 확장과 강제퇴거','2023.9.12. · 주로 2022년 현장 조사','https://www.amnesty.org/en/latest/news/2023/09/drc-cobalt-and-copper-mining-for-batteries-leading-to-human-rights-abuses/')],question:'광물 공급과 에너지 전환 과정에서 주민의 주거·생계·참여권을 어떻게 지킬까?',actors:'지역 주민·광산 기업·정부·배터리 구매 기업·현지 인권단체',scenes:[
scene('아침','이주 이야기를 듣다','광산 확장으로 이주 가능성이 논의되는 가상 상황이다. 가족은 새 거처와 생활에 관한 정보를 충분히 알지 못한다.','주민에게 충분한 정보와 실질적인 의견 반영 절차가 필요하다.',[option('이주 위치·보상·생계 대책에 대한 설명을 요청한다','빠진 정보를 구체화한다. 요청에 답하고 권리를 보장할 책임이 상대에게 있다.'),option('이웃과 함께 필요한 정보를 정리한다','공동의 목소리를 만들 수 있다. 가구별 필요의 차이도 놓치지 않아야 한다.')]),
scene('낮','집의 가격에 담기지 않는 것','가족이 이주할 경우를 생각한다. 집뿐 아니라 일터와 학교, 이웃과의 거리도 바뀔 수 있다.','보상의 적절성은 주택 가격만으로 판단할 수 없다.',[option('새 거처와 생활시설의 조건을 먼저 살펴본다','생활을 이어갈 조건을 확인한다. 이동 비용과 소득 변화도 따져야 한다.'),option('생계와 공동체 관계의 손실을 먼저 정리한다','돈으로 바로 보이지 않는 손실을 드러낸다. 적절한 거처 확보도 함께 필요하다.')]),
scene('저녁','깨끗한 에너지의 조건','우리 지역의 광물이 배터리 생산에 쓰일 수 있다는 설명을 듣는다. 주민 의견을 제안서에 담는다.','환경적 편익이 생산 지역의 인권 침해를 정당화하지 않는다.',[option('주민 참여·정보 공개·구제 절차를 요구한다','의사결정의 조건을 바꾸려 한다. 절차가 형식적으로만 운영되지 않게 확인해야 한다.'),option('구매 기업의 공급망 인권 점검과 피해 회복을 요구한다','책임을 공급망 전체로 넓힌다. 현지 주민의 요구를 중심에 두어야 한다.')])]},
{id:'qatar',country:'카타르',region:'이주노동자의 일터와 생활공간',theme:'인권',title:'일한 만큼 받을 수 있을까',role:'가족에게 생활비를 보내는 성인 이주노동자',wish:'안전하게 일하고 약속된 임금을 제때 받고 싶다.',summary:'제도와 현장에서 누릴 수 있는 권리 사이를 살펴봅니다.',facts:['HRW 세계인권보고서 2025는 노동제도 개선 이후에도 임금 체불, 높은 모집 수수료와 실제 이직의 어려움이 남았다고 보고했다.','폭염 보호 조치가 도입되었으나 보호 수준과 실행의 문제를 지적했다.'],sources:[source('Human Rights Watch · 세계인권보고서 2025: 카타르','주로 2024년 상황','https://www.hrw.org/world-report/2025/country-chapters/qatar')],question:'노동 보호제도가 실제 임금 지급과 안전한 노동으로 이어지려면?',actors:'이주노동자·고용주·노동감독 기관·송출국·노동권 단체',scenes:[
scene('아침','입금되지 않은 임금','약속된 날짜가 지났지만 임금이 들어오지 않은 가상 상황이다. 가족에게 보낼 생활비가 필요하다.','임금 지급은 노동자의 부탁에만 맡길 문제가 아니라 고용주의 책임이다.',[option('근무·급여 기록을 정리하고 지급 일정을 문의한다','문제를 설명할 근거를 모은다. 실제 지급을 보장할 구제 절차도 필요하다.'),option('신뢰할 수 있는 노동 상담 창구 정보를 찾는다','도움받을 경로를 알아본다. 언어와 접근성, 불이익 우려를 함께 해결해야 한다.')]),
scene('낮','더위 속의 작업 일정','더운 날 작업과 휴식 일정에 대한 의견을 모은다. 쉬는 시간을 말하는 것조차 부담스러울 수 있다.','노동자가 요구할 수 있는 힘과 현장 감독의 실효성을 함께 고려해야 한다.',[option('동료와 함께 휴식·작업시간 조정을 요청한다','함께 필요한 조건을 말한다. 요청이 반영되고 불이익이 없도록 보호가 필요하다.'),option('안전 기준과 현장 상담·점검 절차를 확인한다','제도적 경로를 찾는다. 정보 확인만으로 오늘의 환경이 즉시 바뀌지는 않는다.')]),
scene('저녁','다른 일터로 가고 싶다면','이직 가능성을 알아보지만 실제 절차와 생활비가 걱정된다.','법에 있는 권리와 현장에서 행사할 수 있는 권리는 차이가 날 수 있다.',[option('이직 절차와 미지급 임금 구제를 함께 상담한다','여러 문제를 연결해 도움을 찾는다. 처리 기간 동안의 생활 지원이 필요하다.'),option('임금 지급과 현장 감독 개선을 공동 요구로 정리한다','일터의 조건을 바꾸려 한다. 이직을 원하는 개인의 선택권도 보장되어야 한다.')])]}
];
